package com.punjab.oms.ar.service.finance;
import com.punjab.oms.ar.ArApplication;import com.punjab.oms.ar.base.*;import com.punjab.oms.ar.domain.dto.finance.*;import com.punjab.oms.ar.domain.query.finance.LifecycleQuery;import com.punjab.oms.ar.enums.AmountType;
import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.jdbc.core.JdbcTemplate;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;import java.math.BigDecimal;import java.time.LocalDate;import java.nio.file.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
/** scripts/test-mysql-lifecycle：单据生命周期、分页和数据范围。 @author Punjab */
@SpringBootTest(classes=ArApplication.class,webEnvironment=SpringBootTest.WebEnvironment.NONE) @ActiveProfiles("pre")
@EnabledIfSystemProperty(named="ar.lifecycle.real",matches="true") @EnabledIfSystemProperty(named="ar.lifecycle.real.commit",matches="true")
class LifecycleRealTest {
 @DynamicPropertySource static void config(DynamicPropertyRegistry p){p.add("spring.datasource.url",()->"jdbc:mysql://127.0.0.1:13306/oms_ar_test");p.add("spring.datasource.username",()->"oms_ar");p.add("spring.datasource.password",()->System.getenv("AR_TEST_PASSWORD"));}
 @Autowired ReceivableService create;@Autowired ReceivableVoidService voids;@Autowired LifecycleService lifecycle;@Autowired JdbcTemplate jdbc;
 String key(){return UUID.randomUUID().toString();}
 @BeforeEach void setup()throws Exception{assertThat(jdbc.queryForObject("SELECT DATABASE()",String.class)).isEqualTo("oms_ar_test");try(var paths=Files.list(Path.of("../scratch/dbddl"))){for(var path:paths.filter(p->p.getFileName().toString().matches("V\\d+__.*\\.sql")).sorted().toList())for(String sql:Files.readString(path).split(";"))if(!sql.isBlank())jdbc.execute(sql);}CurrentUser.set(new CurrentUser.Identity("lifecycle-test",Set.of(1L),Set.of("ar:create","ar:read","ar:void","ar:void:upstream:WMS")));}
 @AfterEach void clear(){CurrentUser.clear();}
 long create(String source){return create.create(new ReceivableCreateRequest(key(),1L,1L,"CNY","SERVICE",LocalDate.now(),null,"created",List.of(new ReceivableCreateRequest.Line("A",null,AmountType.PRINCIPAL,new BigDecimal("100"),null,null,source==null?null:new ReceivableCreateRequest.Source("WMS","ORDER",source,source,null,key(),"price")))));}
 LifecycleQuery query(long id){var q=new LifecycleQuery();q.setLegalEntityId(1L);q.setDocumentId(id);return q;}
 @Test @DisplayName("生成到作废流水显示完整金额前后及税率字段")void lifecycle(){long doc=create(null);voids.voidDocument(new ReceivableVoidRequest(key(),1L,doc,"cancel"));var result=lifecycle.page(query(doc));assertThat(result.total()).isEqualTo(2);assertThat(result.records()).extracting(r->r.eventType()).containsExactly("RECEIVABLE_VOIDED","CREATED");var line=result.records().getFirst().changes().stream().filter(c->c.objectType().equals("LINE")).findFirst().orElseThrow();assertThat(new java.math.BigDecimal(line.beforeSnapshot().get("openAmount").asText())).isEqualByComparingTo("100");assertThat(new java.math.BigDecimal(line.afterSnapshot().get("openAmount").asText())).isEqualByComparingTo("0");assertThat(line.beforeSnapshot().has("taxRate")).isTrue();assertThat(line.beforeVersion()).isZero();assertThat(line.afterVersion()).isEqualTo(1);}
 @Test @DisplayName("同事件跨单取消只返回当前单据变化且事件不重复计数")void scope(){String source=key();long a=create(source),b=create(source);var canceled=voids.voidUpstream(new UpstreamVoidRequest(key(),1L,"WMS",List.of(new UpstreamVoidRequest.Source("ORDER",source,null)),"two docs"));long ownLine=jdbc.queryForObject("SELECT id FROM oms_ar_line WHERE document_id=?",Long.class,a);var result=lifecycle.page(query(a));assertThat(result.total()).isEqualTo(2);assertThat(result.records().getFirst().id()).isEqualTo(canceled.eventId());assertThat(result.records().getFirst().changes()).allMatch(c->c.objectType().equals("DOCUMENT")?c.objectId().equals(a):c.objectType().equals("LINE") && c.objectId().equals(ownLine));assertThat(result.records().getFirst().changes()).hasSize(2);}
 @Test @DisplayName("分页范围和权限校验包含作废历史")void paging(){long doc=create(null);voids.voidDocument(new ReceivableVoidRequest(key(),1L,doc,"cancel"));var q=query(doc);q.setSize(1);assertThat(lifecycle.page(q).total()).isEqualTo(2);q.setPage(2);assertThat(lifecycle.page(q).records().getFirst().eventType()).isEqualTo("CREATED");q.setPage(Integer.MAX_VALUE);assertThat(lifecycle.page(q).records()).isEmpty();q.setSize(201);assertThatThrownBy(()->lifecycle.page(q)).isInstanceOf(ServiceException.class);var wrong=query(doc);wrong.setLegalEntityId(2L);assertThatThrownBy(()->lifecycle.page(wrong)).isInstanceOf(com.punjab.oms.ar.base.AccessDeniedException.class);}
}
